fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    debug_assert!(k >= 2 && k <= s.len());

    let mut i: usize = 0;
    let mut j: usize = k - 1;

    while i < j {
        s.swap(i, j);
        i += 1;
        j -= 1;
    }
}